import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            n_str = next(iterator)
            n = int(n_str)
            a = []
            for _ in range(n):
                a.append(int(next(iterator)))
        except StopIteration:
            break

        if n == 0:
            results.append("YES")
            continue

        sorted_a = sorted(a)

        possible = True
        for i in range(n):
            if abs(a[i] - sorted_a[i]) > 1:
                possible = False
                break

        if possible:
            results.append("YES")
        else:
            results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
